const brl = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
const formatMoneyInput=(value:string)=>{const digits=value.replace(/\D/g,'');if(!digits)return '';const amount=Number(digits)/100;return new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(amount)};
type TransactionVisualStatus='completed'|'pending'|'overdue';
const subscriptionChargeLabel=(date:string,today:string)=>{const days=Math.round((new Date(date+'T12:00:00').getTime()-new Date(today+'T12:00:00').getTime())/86400000);const value=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(date+'T12:00:00'));return days===0?`${value} • Vence hoje`:days===1?`${value} • Vence amanhã`:days>1&&days<=30?`${value} • em ${days} dias`:value};
const transactionVisualStatus=(item:any,today:string)=>{
  const paid=item.status==='Pago'||item.status==='Efetivada'||Boolean(item.paidAt)||item.paid===true;
  const due=String(item.dateInput||'');
  const kind:TransactionVisualStatus=paid?'completed':due&&due<today?'overdue':'pending';
  const shortDate=due?new Date(due+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}):'';
  const tomorrowDate=new Date(today+'T12:00:00');tomorrowDate.setDate(tomorrowDate.getDate()+1);
  const tomorrow=new Intl.DateTimeFormat('en-CA').format(tomorrowDate);
  const label=kind==='completed'?'Pago':kind==='overdue'?`VENCIDA • ${shortDate}`:!due?'Pendente':due===today?`VENCE HOJE • ${shortDate}`:due===tomorrow?`Vence amanhã • ${shortDate}`:`Vence ${shortDate}`;
  return {kind,label,paid,due,ariaLabel:kind==='completed'?'Transação paga':kind==='overdue'?`Transação vencida em ${new Date(due+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}`:`Transação pendente. ${label}`};
};
