const bankLogo=(domain?:string)=>domain?`https://www.google.com/s2/favicons?domain=${domain}&sz=64`:'';
function BankPicker({editing,setEditing}:{editing:any,setEditing:(value:any)=>void}){
  const [open,setOpen]=useState(false); const [galleryOpen,setGalleryOpen]=useState(false); const [galleryQuery,setGalleryQuery]=useState(''); const normalize=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(); const query=normalize(editing.bank||'');
  const matches=brazilianBanks.filter(bank=>normalize(`${bank.name} ${bank.aliases}`).includes(query)).slice(0,8);
  const galleryBanks=brazilianBanks.filter(bank=>normalize(`${bank.name} ${bank.aliases}`).includes(normalize(galleryQuery)));
  const choose=(bank:typeof brazilianBanks[number])=>{setEditing({...editing,bank:bank.name,bankDomain:bank.domain,bankTheme:bank.theme});setOpen(false);setGalleryOpen(false);setGalleryQuery('')};
  return <><label className="bank-picker">Instituição<div className="bank-input-wrap"><button type="button" className="bank-icon-trigger" onClick={()=>{setOpen(false);setGalleryOpen(true)}} aria-label="Selecionar ícone do cartão" title="Selecionar banco">{editing.bankDomain?<img src={bankLogo(editing.bankDomain)} alt=""/>:<WalletCards size={20}/>}</button><input value={editing.bank} onFocus={()=>setOpen(true)} onChange={e=>setEditing({...editing,bank:e.target.value,bankDomain:'',bankTheme:'neutral'})} placeholder="Digite o nome do banco" autoComplete="off" required/></div>{open&&query&&<div className="bank-suggestions">{matches.length?matches.map(bank=><button type="button" key={bank.name} onMouseDown={e=>e.preventDefault()} onClick={()=>choose(bank)}><img src={bankLogo(bank.domain)} alt=""/><span><b>{bank.name}</b><small>{bank.domain}</small></span></button>):<span className="bank-no-results">Nenhum banco conhecido encontrado. Você pode usar este nome.</span>}</div>}</label>{galleryOpen&&<div className="modal-backdrop bank-gallery-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setGalleryOpen(false)}><div className="modal bank-gallery"><div className="edit-modal-head"><div><span>ÍCONE DO CARTÃO</span><h2>Selecionar banco</h2><p>Escolha uma instituição para usar seu ícone no cartão.</p></div><button type="button" className="icon-button" onClick={()=>setGalleryOpen(false)} aria-label="Fechar"><X/></button></div><label className="bank-gallery-search"><Search size={18}/><input value={galleryQuery} onChange={e=>setGalleryQuery(e.target.value)} placeholder="Buscar banco..." autoFocus/></label><div className="bank-gallery-grid">{galleryBanks.map(bank=><button type="button" className={editing.bankDomain===bank.domain?'active':''} key={bank.name} onClick={()=>choose(bank)}><span><img src={bankLogo(bank.domain)} alt=""/></span><b>{bank.name}</b></button>)}</div>{!galleryBanks.length&&<div className="bank-gallery-empty">Nenhum banco encontrado.</div>}</div></div>}</>;
}
function CardsPage({people,onTransaction,isCouple,hidden}:{people:any;onTransaction:(data:any)=>void;isCouple:boolean;hidden:boolean}){
  const defaultCards:any[]=[];
  const [cards,setCards]=useState<any[]>(defaultCards); const [selectedId,setSelectedId]=useState('nubank-4821'); const [editing,setEditing]=useState<any|null>(null); const [details,setDetails]=useState(false); const [openCardMenu,setOpenCardMenu]=useState<string|null>(null); const [cardTool,setCardTool]=useState<any|null>(null); const [purchases,setPurchases]=useState<any[]>(transactions.filter(t=>t.type==='out'));
  useEffect(()=>{const loadCards=()=>{const saved=localStorage.getItem('juntos-cards');if(saved){const parsed=JSON.parse(saved);setCards(parsed);setSelectedId(current=>parsed.some((item:any)=>item.id===current)?current:(parsed[0]?.id||''))}};const load=()=>{const tx=localStorage.getItem('juntos-transactions');setPurchases((tx?JSON.parse(tx):transactions).filter((t:any)=>t.type==='out'))};loadCards();load();window.addEventListener('juntos-transactions-updated',load);window.addEventListener('juntos-cards-updated',loadCards);return()=>{window.removeEventListener('juntos-transactions-updated',load);window.removeEventListener('juntos-cards-updated',loadCards)}},[]);
  const persist=(next:any[])=>{setCards(next);localStorage.setItem('juntos-cards',JSON.stringify(next));window.dispatchEvent(new Event('juntos-cards-updated'))}; const card=cards.find(c=>c.id===selectedId)||cards[0];
  const cardLabel=(item:any)=>item.last4 ? item.bank+' final '+item.last4 : item.bank;
  const cardPurchases=card?purchases.filter(transaction=>transaction.card===cardLabel(card)):[];
  const openNew=()=>setEditing({id:'card-'+Date.now(),bank:'',last4:'',holder:people.Rafael.name.toUpperCase()||'',invoice:'0',limit:'0',closing:new Date().toISOString().slice(0,10),dueDay:'10',future:'0',bankDomain:'',bankTheme:'neutral',scope:'personal',isNew:true});
  const saveCard=(e:React.FormEvent)=>{e.preventDefault();const clean={...editing,invoice:Number(String(editing.invoice).replace(/[.]/g,'').replace(',','.')),limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.')),future:Number(String(editing.future).replace(/[.]/g,'').replace(',','.')),dueDay:Number(editing.dueDay)};delete clean.isNew;if(!clean.bank.trim()||(clean.last4&&clean.last4.length!==4)||!clean.holder.trim()||clean.limit<=0||!clean.closing||clean.dueDay<1||clean.dueDay>31){appAction('Preencha os dados obrigatórios, informe um limite maior que zero e um vencimento entre os dias 1 e 31.');return}const next=editing.isNew?[...cards,clean]:cards.map(c=>c.id===clean.id?clean:c);persist(next);setSelectedId(clean.id);setEditing(null);appAction(editing.isNew?'Cartão criado com sucesso.':'Cartão atualizado com sucesso.')};
  const removeCard=async()=>{if(!editing||!await confirmDialog(`Excluir o cartão ${editing.bank}?`))return;const next=cards.filter(c=>c.id!==editing.id);persist(next);setSelectedId(next[0]?.id||'');setEditing(null);appAction('Cartão excluído.')};
  const deleteCard=async(item:any)=>{if(!await confirmDialog(`Excluir o cartão ${item.bank}?`))return;const next=cards.filter(c=>c.id!==item.id);persist(next);if(item.id===card.id)setSelectedId(next[0]?.id||'');setCardTool(null);appAction('Cartão excluído.');};
  const pay=async()=>{if(!card||!await confirmDialog(`Confirmar pagamento de ${brl(card.invoice)}?`))return;const value=Number(card.invoice);persist(cards.map(c=>c.id===card.id?{...c,invoice:0}:c));if(value>0)onTransaction({title:`Pagamento da fatura - ${card.bank}`,category:'Dívidas',person:'Rafael',account:'Carteira',payment:'Boleto',card:'',date:new Intl.DateTimeFormat('en-CA').format(new Date()),value,type:'out',icon:'💳',schedule:'once'});appAction('Fatura paga e registrada nas transações.')};
  const safeCardNumbers=(item:any)=>{const invoice=Math.max(0,Number(item?.invoice)||0),limit=Math.max(0,Number(item?.limit)||0),available=Math.max(0,limit-invoice),rawPercent=limit>0?Math.max(0,Math.round(invoice/limit*100)):0;return {invoice,limit,available,rawPercent,barPercent:Math.min(100,rawPercent)}};
  const cardTotals=useMemo(()=>cards.reduce((totals,item)=>{const values=safeCardNumbers(item);return {invoice:totals.invoice+values.invoice,limit:totals.limit+values.limit,available:totals.available+values.available}}, {invoice:0,limit:0,available:0}),[cards]);
  const totalUsedPercent=cardTotals.limit>0?Math.max(0,Math.round(cardTotals.invoice/cardTotals.limit*100)):0;
  const displayMoney=(value:number)=>hidden?'••••••':brl(value);
  const cardDate=(value?:string)=>value?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(value+'T12:00:00')).replace('.',''):null;
  if(!card)return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Nenhum cartão cadastrado.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div><section className="card cards-empty-state"><WalletCards size={30}/><h2>Nenhum cart&atilde;o cadastrado</h2><p>Cadastre seu primeiro cart&atilde;o para acompanhar limites, faturas e compras.</p><button className="primary" onClick={openNew}><Plus size={17}/> Adicionar cart&atilde;o</button></section>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><div className="card-editor-subhead"><p>Edite todos os dados, limites e datas.</p><button className="primary card-header-save"><Check size={16}/> Salvar cartão</button></div></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><BankPicker editing={editing} setEditing={setEditing}/><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label>{isCouple&&<label>Uso do cartão<select value={editing.scope||'personal'} onChange={e=>setEditing({...editing,scope:e.target.value})}><option value="personal">Pessoal</option><option value="shared">Conjunto</option></select></label>}<label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:formatMoneyInput(e.target.value)})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:formatMoneyInput(e.target.value)})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Dia do vencimento<input type="number" min="1" max="31" value={editing.dueDay||''} onChange={e=>setEditing({...editing,dueDay:e.target.value.replace(/\D/g,'')})} placeholder="Ex.: 10" required/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:formatMoneyInput(e.target.value)})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button></div></form></div>}</div>;
  const closingLabel=card.closing?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(new Date(card.closing+'T12:00:00')):'Não informado';
  return <div className="page-stack cards-page"><div className="page-heading cards-page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Limites e faturas sob controle.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div>
    <section className="cards-summary" aria-label="Resumo dos cartões"><div><span>Faturas atuais</span><strong>{displayMoney(cardTotals.invoice)}</strong></div><div><span>Limite total</span><strong>{displayMoney(cardTotals.limit)}</strong></div><div><span>Disponível</span><strong>{displayMoney(cardTotals.available)}</strong></div><div><span>Limite utilizado</span><strong>{totalUsedPercent}%</strong></div></section>
    <section className="cards-wallet"><div className="cards-wallet-head"><div><span>Meus cartões</span><h2>{cards.length} {cards.length===1?'cartão':'cartões'}</h2></div><small>Selecione um cartão para consultar suas compras</small></div>
      <div className="cards-wallet-layout"><div className="cards-wallet-list">{cards.map(item=>{const values=safeCardNumbers(item),selected=item.id===card.id,itemClosing=cardDate(item.closing),usageTone=values.rawPercent>=100?'limit':values.rawPercent>=80?'alert':values.rawPercent>=50?'attention':'normal';return <article className={'wallet-card card bank-theme-'+(item.bankTheme||item.color||'neutral')+' '+(selected?'active ':'')+'usage-'+usageTone} key={item.id}>
        <button type="button" className="wallet-card-select" onClick={()=>setSelectedId(item.id)} aria-expanded={selected} aria-controls={'card-details-'+item.id}><span className={'card-brand-icon '+(item.bankDomain?'has-logo':'')}>{item.bankDomain?<img className="card-bank-logo" src={bankLogo(item.bankDomain)} alt="" onError={event=>{event.currentTarget.style.display='none'}}/>:<CreditCard size={23}/>}</span><span className="wallet-card-copy"><b title={item.bank}>{item.bank}</b><small title={item.holder}>{item.holder}{(item.scope||'personal')==='shared'?' · conjunto':''}</small><strong>Fatura {displayMoney(values.invoice)}</strong><em>Disponível {displayMoney(values.available)}</em></span><span className={'wallet-card-status '+(values.invoice>0?'open':'closed')}><i/>{values.invoice>0?'Aberta':'Fechada'}</span><ChevronRight className="wallet-card-chevron" size={18}/></button>
        <span className="wallet-card-tools" onClick={event=>event.stopPropagation()}><button type="button" className="card-quick-add" onClick={()=>window.dispatchEvent(new CustomEvent('juntos-card-expense',{detail:{card:cardLabel(item)}}))} aria-label={'Adicionar compra em '+item.bank} title="Adicionar compra"><Plus size={16}/><span>Compra</span></button><span className="card-menu-wrap"><button type="button" className="card-menu-trigger" onClick={()=>setOpenCardMenu(openCardMenu===item.id?null:item.id)} aria-label={'Opções de '+item.bank} aria-expanded={openCardMenu===item.id}><MoreHorizontal size={19}/></button>{openCardMenu===item.id&&<span className="card-options-menu"><button type="button" onClick={()=>{setEditing({...item,invoice:String(item.invoice).replace('.',','),limit:String(item.limit).replace('.',','),future:String(item.future).replace('.',',')});setOpenCardMenu(null)}}>Editar</button><button type="button" onClick={()=>{setCardTool({type:'adjust',card:item,value:String(values.invoice).replace('.',',')});setOpenCardMenu(null)}}>Reajustar fatura</button><button type="button" onClick={()=>{setCardTool({type:'history',card:item});setOpenCardMenu(null)}}>Histórico</button><button type="button" onClick={()=>{setCardTool({type:'details',card:item});setOpenCardMenu(null)}}>Detalhes</button><button type="button" onClick={()=>{setCardTool({type:'evolution',card:item});setOpenCardMenu(null)}}>Evolução mensal</button><button type="button" onClick={()=>{setCardTool({type:'calculator',card:item,value:'',installments:'1',interest:'0'});setOpenCardMenu(null)}}>Calculadora</button><button type="button" className="danger" onClick={()=>{setOpenCardMenu(null);void deleteCard(item)}}>Excluir</button></span>}</span></span>
        {selected&&<div className="wallet-mobile-details" id={'card-details-'+item.id}><div className="wallet-invoice"><span>Fatura atual</span><strong>{displayMoney(values.invoice)}</strong><i className={values.invoice>0?'open':'closed'}>{values.invoice>0?'Fatura aberta':'Fatura fechada'}</i></div><div className="wallet-secondary-values"><span><small>Limite</small><b>{displayMoney(values.limit)}</b></span><span><small>Disponível</small><b>{displayMoney(values.available)}</b></span></div><div className="wallet-usage"><span>Limite utilizado <b>{values.rawPercent}%</b></span><div><i style={{width:String(values.barPercent)+'%'}}/></div></div>{(itemClosing||item.dueDay)&&<div className="wallet-dates">{itemClosing&&<span><CalendarDays size={15}/><small>Fecha</small><b>{itemClosing}</b></span>}{item.dueDay&&<span><CalendarDays size={15}/><small>Vence</small><b>Dia {item.dueDay}</b></span>}</div>}<button type="button" className="ghost wallet-purchases-button" onClick={()=>setCardTool({type:'history',card:item})}>Ver compras</button></div>}
      </article>})}</div>
      <article className="card wallet-detail-panel" id={'card-details-'+card.id}>{(()=>{const values=safeCardNumbers(card),itemClosing=cardDate(card.closing),usageTone=values.rawPercent>=100?'limit':values.rawPercent>=80?'alert':values.rawPercent>=50?'attention':'normal';return <><div className="wallet-detail-head"><span className={'card-brand-icon '+(card.bankDomain?'has-logo':'')}>{card.bankDomain?<img className="card-bank-logo" src={bankLogo(card.bankDomain)} alt="" onError={event=>{event.currentTarget.style.display='none'}}/>:<CreditCard size={25}/>}</span><span><small>Cartão selecionado</small><h2>{card.bank}</h2><p title={card.holder}>Titular: {card.holder}{(card.scope||'personal')==='shared'?' · Cartão conjunto':''}</p></span><i className={values.invoice>0?'open':'closed'}>{values.invoice>0?'Fatura aberta':'Fatura fechada'}</i></div><div className="wallet-invoice"><span>Fatura atual</span><strong>{displayMoney(values.invoice)}</strong></div><div className="wallet-secondary-values"><span><small>Limite total</small><b>{displayMoney(values.limit)}</b></span><span><small>Disponível</small><b>{displayMoney(values.available)}</b></span></div><div className={'wallet-usage usage-'+usageTone}><span>Limite utilizado <b>{values.rawPercent}%</b></span><div><i style={{width:String(values.barPercent)+'%'}}/></div></div>{(itemClosing||card.dueDay)&&<div className="wallet-dates">{itemClosing&&<span><CalendarDays size={16}/><small>Próximo fechamento</small><b>{itemClosing}</b></span>}{card.dueDay&&<span><CalendarDays size={16}/><small>Vencimento</small><b>Dia {card.dueDay}</b></span>}</div>}<div className="wallet-detail-actions"><button type="button" className="primary" onClick={()=>window.dispatchEvent(new CustomEvent('juntos-card-expense',{detail:{card:cardLabel(card)}}))}><Plus size={16}/> Adicionar compra</button><button type="button" className="ghost" onClick={()=>setCardTool({type:'history',card})}>Ver compras</button></div></>})()}</article></div>
    </section>
            {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><div className="card-editor-subhead"><p>Edite todos os dados, limites e datas.</p><button className="primary card-header-save"><Check size={16}/> Salvar cartão</button></div></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><BankPicker editing={editing} setEditing={setEditing}/><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label>{isCouple&&<label>Uso do cartão<select value={editing.scope||'personal'} onChange={e=>setEditing({...editing,scope:e.target.value})}><option value="personal">Pessoal</option><option value="shared">Conjunto</option></select></label>}<label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:formatMoneyInput(e.target.value)})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:formatMoneyInput(e.target.value)})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Dia do vencimento<input type="number" min="1" max="31" value={editing.dueDay||''} onChange={e=>setEditing({...editing,dueDay:e.target.value.replace(/\D/g,'')})} placeholder="Ex.: 10" required/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:formatMoneyInput(e.target.value)})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button></div></form></div>}
    {details&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDetails(false)}><div className="modal card-details"><div className="edit-modal-head"><div><span>RESUMO DO CARTÃO</span><h2>{card.bank} {card.last4?`•••• ${card.last4}`:''}</h2></div><button className="icon-button" onClick={()=>setDetails(false)}><X/></button></div><div className="details-list"><div><span>Fatura atual</span><b>{brl(card.invoice)}</b></div><div><span>Limite total</span><b>{brl(card.limit)}</b></div><div><span>Limite disponível</span><b>{brl(Math.max(0,card.limit-card.invoice))}</b></div><div><span>Próximo fechamento</span><b>{closingLabel}</b></div><div><span>Vencimento</span><b>{card.dueDay?'Dia '+card.dueDay:'Não informado'}</b></div><div><span>Parcelas futuras</span><b>{brl(card.future)}</b></div></div><div className="edit-modal-actions"><span/><button className="primary" onClick={()=>setDetails(false)}>Fechar</button></div></div></div>}
    {cardTool&&<div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setCardTool(null)}><div className="modal card-tool-modal"><div className="edit-modal-head"><div><span>GESTÃO DO CARTÃO</span><h2>{cardTool.type==='adjust'?'Reajustar fatura':cardTool.type==='history'?'Histórico de compras':cardTool.type==='details'?'Detalhes do cartão':cardTool.type==='evolution'?'Evolução mensal':'Calculadora de compras'}</h2><p>{cardTool.card.bank} · {cardTool.card.holder}</p></div><button type="button" className="icon-button" onClick={()=>setCardTool(null)}><X/></button></div>{cardTool.type==='adjust'&&<form className="card-tool-form" onSubmit={event=>{event.preventDefault();const value=Number(String(cardTool.value).replace(/[.]/g,'').replace(',','.'));if(value<0)return;persist(cards.map(item=>item.id===cardTool.card.id?{...item,invoice:value}:item));setCardTool(null);appAction('Fatura reajustada com sucesso.')}}><label>Novo valor da fatura<input value={cardTool.value} onChange={event=>setCardTool({...cardTool,value:formatMoneyInput(event.target.value)})} inputMode="decimal" autoFocus required/></label><div className="card-tool-actions"><button type="button" className="ghost" onClick={()=>setCardTool(null)}>Cancelar</button><button className="primary">Salvar reajuste</button></div></form>}{cardTool.type==='history'&&<div className="card-tool-content">{purchases.filter(item=>item.card===cardLabel(cardTool.card)).length?purchases.filter(item=>item.card===cardLabel(cardTool.card)).map(item=><div className="card-history-row" key={item.id}><span><b>{displayTitle(people,item.title)}</b><small>{item.category} · {item.date}</small></span><strong>{brl(item.value)}</strong></div>):<div className="organizer-empty">Nenhuma compra registrada neste cartão.</div>}</div>}{cardTool.type==='details'&&<div className="card-tool-content details-list"><div><span>Titular</span><b>{cardTool.card.holder}</b></div><div><span>Limite total</span><b>{brl(Number(cardTool.card.limit)||0)}</b></div><div><span>Fatura atual</span><b>{brl(Number(cardTool.card.invoice)||0)}</b></div><div><span>Status</span><b>{Number(cardTool.card.invoice)>0?'Aberta':'Fechada'}</b></div><div><span>Limite disponível</span><b>{brl(Math.max(0,Number(cardTool.card.limit)-Number(cardTool.card.invoice)))}</b></div><div><span>Próximo fechamento</span><b>{cardTool.card.closing?new Date(cardTool.card.closing+'T12:00:00').toLocaleDateString('pt-BR'):'Não informado'}</b></div><div><span>Vencimento</span><b>{cardTool.card.dueDay?'Dia '+cardTool.card.dueDay:'Não informado'}</b></div></div>}{cardTool.type==='evolution'&&<div className="card-tool-content">{(()=>{const monthly=new Map<string,number>();purchases.filter(item=>item.card===cardLabel(cardTool.card)&&item.dateInput).forEach(item=>{const month=item.dateInput.slice(0,7);monthly.set(month,(monthly.get(month)||0)+Number(item.value||0))});const rows=[...monthly.entries()].sort((a,b)=>a[0].localeCompare(b[0])).slice(-6);const max=Math.max(...rows.map(row=>row[1]),1);return rows.length?<div className="monthly-evolution">{rows.map(([month,value])=><div key={month}><span>{new Date(month+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'2-digit'})}</span><div><i style={{width:`${value/max*100}%`}}/></div><b>{brl(value)}</b></div>)}</div>:<div className="organizer-empty">Ainda não há compras com data suficiente para calcular a evolução.</div>})()}</div>}{cardTool.type==='calculator'&&<div className="card-tool-form"><label>Valor da compra<input value={cardTool.value} onChange={event=>setCardTool({...cardTool,value:formatMoneyInput(event.target.value)})} inputMode="decimal" placeholder="0,00"/></label><label>Parcelas<input type="number" min="1" max="48" value={cardTool.installments} onChange={event=>setCardTool({...cardTool,installments:event.target.value})}/></label><label>Juros totais (%)<input value={cardTool.interest} onChange={event=>setCardTool({...cardTool,interest:event.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal"/></label>{(()=>{const value=Number(String(cardTool.value).replace(/[.]/g,'').replace(',','.'))||0;const installments=Math.max(1,Number(cardTool.installments)||1);const interest=Number(String(cardTool.interest).replace(',','.'))||0;const total=value*(1+interest/100);return <div className="calculator-result"><span>Total estimado<b>{brl(total)}</b></span><span>Valor por parcela<b>{brl(total/installments)} × {installments}</b></span><span>Limite após a compra<b>{brl(Math.max(0,Number(cardTool.card.limit)-Number(cardTool.card.invoice)-total))}</b></span></div>})()}</div>}</div></div>}  </div>
}

function GoalsPage({onTransaction,isCouple,people,hidden}:{onTransaction:(data:any)=>void;isCouple:boolean;people:any;hidden:boolean}){
  const initialGoals:any[]=[];
  const [items,setItems]=useState<any[]>(initialGoals); const [editing,setEditing]=useState<any|null>(null); const [contribution,setContribution]=useState<any|null>(null); const [depositHistory,setDepositHistory]=useState<any|null>(null); const [goalAccounts,setGoalAccounts]=useState<any[]>([]); const [goalFilter,setGoalFilter]=useState<'all'|'active'|'completed'|'shared'>('all');
  useEffect(()=>{const saved=localStorage.getItem('juntos-goals');if(saved)setItems(JSON.parse(saved));try{setGoalAccounts(JSON.parse(localStorage.getItem('juntos-accounts')||'[]'))}catch{setGoalAccounts([])}},[]); const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-goals',JSON.stringify(next));window.dispatchEvent(new Event('juntos-goals-updated'))};
  const openNew=()=>setEditing({id:Date.now(),title:'',emoji:'🎯',current:'0',total:'',color:'#7c3aed',date:'Dez 2026',sourceAccount:'Carteira',scope:'personal',owner:'Rafael',isNew:true});
  const monthsUntilGoal=(input:any)=>{const value=String(input||'').trim().toLowerCase();const normalized=value.normalize('NFD').replace(/[\u0300-\u036f]/g,'');const monthNames=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];let year=0,month=-1;if(/^\d{4}-\d{2}/.test(value)){year=Number(value.slice(0,4));month=Number(value.slice(5,7))-1}else{const yearMatch=value.match(/(20\d{2})/);const monthIndex=monthNames.findIndex(name=>normalized.includes(name));if(yearMatch){year=Number(yearMatch[1]);month=monthIndex}}if(!year||month<0)return 12;const today=new Date();return Math.max(1,(year-today.getFullYear())*12+month-today.getMonth()+1)};
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,current:Number(String(editing.current).replace(/[.]/g,'').replace(',','.')),total:Number(String(editing.total).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.title.trim()||item.total<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Meta criada com sucesso.':'Meta atualizada com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir a meta “${editing.title}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Meta excluída.')}};
  const addMoney=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(contribution.value).replace(/[.]/g,'').replace(',','.'));if(value<=0)return;const goal=contribution.goal;const previousDeposit=contribution.deposit;const depositId=previousDeposit?.id||Date.now();const depositedAt=previousDeposit?.depositedAt||new Date().toISOString();const deposit={id:depositId,value,depositedAt};persist(items.map(x=>x.id===goal.id?{...x,current:Math.max(0,Number(x.current||0)+(previousDeposit?value-Number(previousDeposit.value||0):value)),deposits:previousDeposit?(x.deposits||[]).map((entry:any)=>entry.id===depositId?deposit:entry):[deposit,...(x.deposits||[])]}:x));if(previousDeposit){try{const saved=JSON.parse(localStorage.getItem('juntos-transactions')||'[]');localStorage.setItem('juntos-transactions',JSON.stringify(saved.map((item:any)=>item.goalDepositId===depositId?{...item,value}:item)));window.dispatchEvent(new Event('juntos-transactions-updated'))}catch{}appAction('Depósito atualizado com sucesso.')}else{onTransaction({title:`Aporte na meta - ${goal.title}`,category:'Investimentos / Construção de Patrimônio',person:goal.scope==='shared'?'Casal':(goal.owner||'Rafael'),account:'Carteira',payment:'Transferência',card:'',date:new Intl.DateTimeFormat('en-CA').format(new Date()),value,type:'out',icon:goal.emoji||'🎯',scope:goal.scope||'personal',schedule:'once',goalDepositId:depositId});appAction('Depósito registrado nas transações.')}setContribution(null)};
  const removeGoalDeposit=async(goal:any,deposit:any)=>{if(!await confirmDialog(`Excluir o depósito de ${brl(Number(deposit.value||0))}?`,'Excluir depósito?'))return;const latest=items.find(item=>item.id===goal.id)||goal;const nextGoal={...latest,current:Math.max(0,Number(latest.current||0)-Number(deposit.value||0)),deposits:(latest.deposits||[]).filter((entry:any)=>entry.id!==deposit.id)};persist(items.map(item=>item.id===goal.id?nextGoal:item));try{const saved=JSON.parse(localStorage.getItem('juntos-transactions')||'[]');localStorage.setItem('juntos-transactions',JSON.stringify(saved.filter((item:any)=>item.goalDepositId!==deposit.id)));window.dispatchEvent(new Event('juntos-transactions-updated'))}catch{}setDepositHistory(nextGoal);appAction('Depósito excluído com sucesso.')};
  const isGoalCompleted=(goal:any)=>{const current=Math.max(0,Number(goal.current)||0);const total=Math.max(0,Number(goal.total)||0);return total>0&&Math.round(current/total*100)>=100};
  const goalStats=items.reduce((stats,g)=>{const current=Math.max(0,Number(g.current)||0);const total=Math.max(0,Number(g.total)||0);const completed=isGoalCompleted(g);stats.active+=completed?0:1;stats.completed+=completed?1:0;stats.current+=current;stats.remaining+=Math.max(0,total-current);return stats},{active:0,completed:0,current:0,remaining:0});
  const visibleGoals=[...items].filter(g=>{const completed=isGoalCompleted(g);return goalFilter==='all'||(goalFilter==='active'&&!completed)||(goalFilter==='completed'&&completed)||(goalFilter==='shared'&&(g.scope||'personal')==='shared')}).sort((a,b)=>{const aDone=isGoalCompleted(a),bDone=isGoalCompleted(b);if(aDone!==bDone)return aDone?1:-1;const aPct=Number(a.total)>0?Number(a.current)/Number(a.total):0,bPct=Number(b.total)>0?Number(b.current)/Number(b.total):0;return bPct-aPct});
  const goalMoney=(value:number)=>hidden?'••••••':brl(value);
  return <div className="page-stack goals-page"><div className="page-heading goals-page-heading"><div><p>Meus objetivos</p><h1>Metas</h1><span>Cada passo aproxima você do futuro.</span></div><button className="primary" onClick={openNew}><Plus size={17}/> Nova meta</button></div>
    <section className="goals-summary" aria-label="Resumo das metas"><article><span>Metas ativas</span><strong>{goalStats.active}</strong></article><article><span>Concluídas</span><strong>{goalStats.completed}</strong></article><article><span>Total acumulado</span><strong>{goalMoney(goalStats.current)}</strong></article><article><span>Falta alcançar</span><strong>{goalMoney(goalStats.remaining)}</strong></article></section>
    <div className="goals-section-head"><div><span>Seus objetivos</span><h2>Minhas metas</h2></div><div className="goal-filters" role="group" aria-label="Filtrar metas">{([['all','Todas'],['active','Ativas'],['completed','Concluídas'],['shared','Compartilhadas']] as const).map(([value,label])=><button type="button" className={goalFilter===value?'active':''} onClick={()=>setGoalFilter(value)} aria-pressed={goalFilter===value} key={value}>{label}</button>)}</div></div>
    {items.length===0?<section className="card goals-empty"><Target size={29}/><h2>Nenhuma meta criada ainda</h2><p>Transforme seus planos em objetivos.</p><button className="primary" onClick={openNew}><Plus size={17}/> Criar primeira meta</button></section>:visibleGoals.length===0?<section className="card goals-empty compact"><p>Nenhuma meta encontrada neste filtro.</p></section>:<div className="goal-page-grid">{visibleGoals.map(g=>{const current=Math.max(0,Number(g.current)||0);const total=Math.max(0,Number(g.total)||0);const rawPct=total>0?Math.max(0,Math.round(current/total*100)):0;const barPct=Math.min(100,rawPct);const remaining=Math.max(0,total-current);const achieved=isGoalCompleted(g);const exceeded=Math.max(0,current-total);return <article className={`card big-goal ${achieved?'achieved':''}`} key={g.id}>
      <button className="goal-compact-head" onClick={()=>setEditing({...g,current:String(g.current).replace('.',','),total:String(g.total).replace('.',',')})} aria-label={`Editar meta ${g.title}`}><i style={{background:`color-mix(in srgb,${g.color} 15%,var(--surface))`}}>{g.emoji}</i><span><strong>{g.title}</strong><small>{(g.scope||'personal')==='shared'?'👥 Compartilhada':g.owner==='Mariana'?'Meta do parceiro(a)':'Individual'}</small></span><b>{rawPct}%</b></button>
      <div className="goal-compact-body"><div className="goal-values"><span><b>{goalMoney(current)}</b> de {goalMoney(total)}</span><strong>{rawPct}%</strong></div><div className="progress" role="progressbar" aria-label={`Progresso de ${g.title}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={barPct}><span style={{width:`${barPct}%`,background:achieved?'#15875d':g.color}}/></div>
      <div className={`goal-status ${achieved?'completed':''}`}>{achieved?<><Check size={15}/><span>{exceeded>0?<>Meta superada em <b>{goalMoney(exceeded)}</b></>:<><b>✓ Meta concluída!</b><small>Parabéns! Você atingiu seu objetivo.</small></>}</span></>:<span>{current<=0?<small>Ainda nenhum depósito</small>:null}<b>Faltam {goalMoney(remaining)}</b></span>}</div>
      <div className="goal-card-actions">{!achieved&&<button className="primary" onClick={()=>setContribution({goal:g,value:''})} aria-label={`Depositar na meta ${g.title}`}><Plus size={15}/> Depositar</button>}<button className="ghost" onClick={()=>setDepositHistory(g)} aria-label={`Ver depósitos da meta ${g.title}`}>Ver depósitos</button></div></div></article>})}</div>}            {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal goal-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA META':'EDITAR META'}</span><h2>{editing.isNew?'Criar uma meta':'Atualizar meta'}</h2><p>Personalize o objetivo e acompanhe o progresso.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Nome da meta<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Viagem para Itália" required/></label><label className="field-full">Ícone selecionado<div className="goal-icon-search"><Search size={17}/><input value={editing.iconQuery||''} onChange={e=>setEditing({...editing,iconQuery:e.target.value})} placeholder="Procurar: casa, viagem, esporte..." aria-label="Procurar ícones"/></div><div className="goal-icon-picker"><span>{editing.emoji||'🎯'}</span><div>{CATEGORY_ICON_GROUPS.filter(group=>!editing.iconQuery||normalizeIconSearch(group.name+' '+(GOAL_ICON_SEARCH_TERMS[group.name]||'')).includes(normalizeIconSearch(editing.iconQuery.trim()))).flatMap(group=>group.icons).filter((icon,index,all)=>all.indexOf(icon)===index).map((icon,index)=><button type="button" className={editing.emoji===icon?'active':''} onClick={()=>setEditing({...editing,emoji:icon})} key={`${icon}-${index}`}>{icon}</button>)}</div></div></label><label>Responsável<select value={(editing.scope||'personal')==='shared'?'Casal':(editing.owner||'Rafael')} onChange={e=>{const owner=e.target.value;setEditing({...editing,owner,scope:owner==='Casal'?'shared':'personal'})}}><option value="Rafael">{people.Rafael.name||'Você'}</option>{isCouple&&<><option value="Mariana">{people.Mariana.name||'Parceiro(a)'}</option><option value="Casal">Casal</option></>}</select></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label><label>Saldo inicial<input value={editing.current} onChange={e=>setEditing({...editing,current:formatMoneyInput(e.target.value)})} inputMode="decimal"/></label><label>Conta<select value={editing.sourceAccount||'Carteira'} onChange={e=>setEditing({...editing,sourceAccount:e.target.value})} required><option value="Carteira">Carteira</option>{goalAccounts.filter(account=>account.name!=='Carteira').map(account=><option value={account.name} key={account.id}>{account.name}{account.bank?` · ${account.bank}`:''}</option>)}</select></label><label>Valor da meta<input value={editing.total} onChange={e=>setEditing({...editing,total:formatMoneyInput(e.target.value)})} inputMode="decimal" required/></label><label className="field-full">Previsão de conclusão<input value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} placeholder="Ex.: Novembro de 2027"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir meta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar meta</button></div></form></div>}
    {depositHistory&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDepositHistory(null)}><div className="modal goal-deposit-modal"><div className="edit-modal-head"><div><span>HISTÓRICO DA META</span><h2>Depósitos realizados</h2><p>{depositHistory.emoji} {depositHistory.title}</p></div><button type="button" className="icon-button" onClick={()=>setDepositHistory(null)}><X/></button></div><section className="goal-deposit-history"><div><span><b>Todos os depósitos</b><small>{(depositHistory.deposits||[]).length} {(depositHistory.deposits||[]).length===1?'depósito registrado':'depósitos registrados'}</small></span><button type="button" className="primary" onClick={()=>{const goal=items.find(item=>item.id===depositHistory.id)||depositHistory;setDepositHistory(null);setContribution({goal,value:''})}}>Depositar</button></div>{(depositHistory.deposits||[]).length?<div className="goal-deposit-list">{[...(depositHistory.deposits||[])].sort((a:any,b:any)=>String(b.depositedAt).localeCompare(String(a.depositedAt))).map((deposit:any)=><article key={deposit.id}><span><b>{brl(Number(deposit.value||0))}</b><small>{new Date(deposit.depositedAt).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</small></span><div className="goal-deposit-actions"><button type="button" className="icon-button" onClick={()=>{const goal=items.find(item=>item.id===depositHistory.id)||depositHistory;setDepositHistory(null);setContribution({goal,deposit,value:String(deposit.value).replace('.',',')})}} aria-label="Editar depósito" title="Editar depósito"><Pencil size={16}/></button><button type="button" className="icon-button danger" onClick={()=>removeGoalDeposit(depositHistory,deposit)} aria-label="Excluir depósito" title="Excluir depósito"><X size={16}/></button></div></article>)}</div>:<p>Nenhum depósito registrado individualmente ainda.</p>}</section><div className="edit-modal-actions"><span/><button type="button" className="primary" onClick={()=>setDepositHistory(null)}>Fechar</button></div></div></div>}    {contribution&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setContribution(null)}><form className="modal contribution-modal" onSubmit={addMoney}><div className="edit-modal-head"><div><span>{contribution.deposit?'EDITAR DEPÓSITO':'NOVO DEPÓSITO'}</span><h2>{contribution.deposit?'Editar depósito':'Depositar'}</h2><p>{contribution.goal.emoji} {contribution.goal.title}</p></div><button type="button" className="icon-button" onClick={()=>setContribution(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Valor do depósito<input value={contribution.value} onChange={e=>setContribution({...contribution,value:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal" autoFocus required/><small>O valor será retirado automaticamente da Carteira.</small></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setContribution(null)}>Cancelar</button><button type="submit" className="primary">{contribution.deposit?'Salvar alteração':'Confirmar depósito'}</button></div></form></div>}
  </div>
}

function CalendarPage({people}:{people:any}){
  const initialEvents:any[]=[];
  const [month,setMonth]=useState(new Date()); const [events,setEvents]=useState<any[]>(initialEvents); const [calendarTransactions,setCalendarTransactions]=useState<any[]>([]); const [calendarValueVisibility,setCalendarValueVisibility]=useState({income:true,expense:true}); const [editing,setEditing]=useState<any|null>(null); const [calendarFilter,setCalendarFilter]=useState<'all'|'income'|'expense'>('all'); const [selectedDate,setSelectedDate]=useState<string|null>(null); const [showAllUpcoming,setShowAllUpcoming]=useState(false);
  useEffect(()=>{const load=()=>{try{const saved=localStorage.getItem('juntos-calendar-events');setEvents(saved?JSON.parse(saved):[]);const savedTransactions=localStorage.getItem('juntos-transactions');setCalendarTransactions(savedTransactions?JSON.parse(savedTransactions):[]);const savedVisibility=JSON.parse(localStorage.getItem('juntos-calendar-value-visibility')||'null');if(savedVisibility)setCalendarValueVisibility(previous=>({...previous,...savedVisibility}))}catch{setEvents([]);setCalendarTransactions([])}};load();window.addEventListener('juntos-calendar-updated',load);window.addEventListener('juntos-transactions-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-calendar-updated',load);window.removeEventListener('juntos-transactions-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const persist=(next:any[])=>{setEvents(next);localStorage.setItem('juntos-calendar-events',JSON.stringify(next));window.dispatchEvent(new Event('juntos-calendar-updated'))};
  const toggleCalendarValues=(key:'income'|'expense')=>setCalendarValueVisibility(previous=>{const next={...previous,[key]:!previous[key]};localStorage.setItem('juntos-calendar-value-visibility',JSON.stringify(next));return next});
  const calendarValue=(item:any)=>calendarValueVisibility[item.type==='income'?'income':'expense']?(item.value?brl(Number(item.value)):'—'):'••••'; const calendarCategory=(item:any)=>item.category||({bill:'Conta',income:'Receita',card:'Cartão',sub:'Assinatura',goal:'Meta'} as Record<string,string>)[item.type]||'Evento'; const calendarStatusClass=(item:any)=>{if(item.type==='income')return 'calendar-income';if(item.status==='Pago'||item.status==='Efetivada'||item.paidAt||item.paid)return 'calendar-paid';const current=new Intl.DateTimeFormat('en-CA').format(new Date());return item.date<current?'calendar-overdue':'calendar-upcoming'};
  const year=month.getFullYear(),monthIndex=month.getMonth(),daysInMonth=new Date(year,monthIndex+1,0).getDate(),startDay=new Date(year,monthIndex,1).getDay(); const cells=Array.from({length:42},(_,i)=>i-startDay+1); const monthKey=`${year}-${String(monthIndex+1).padStart(2,'0')}`;
  const openNew=(date?:string)=>setEditing({id:Date.now(),title:'',date:date||`${monthKey}-${String(Math.min(new Date().getDate(),daysInMonth)).padStart(2,'0')}`,type:'bill',value:'',person:'Rafael',notes:'',status:'Pendente',paidAt:null,isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value||0).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;persist(editing.isNew?[...events,item]:events.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Evento criado no calendário.':'Evento atualizado com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.title}”?`)){persist(events.filter(x=>x.id!==editing.id));setEditing(null);appAction('Evento excluído do calendário.')}};
  const transactionEvents=calendarTransactions.filter(item=>item.dateInput).map(item=>({id:`transaction-${item.id}`,transactionId:item.id,title:item.title,category:item.category||'Outros',date:item.dateInput,type:item.type==='in'?'income':'bill',value:Number(item.value)||0,status:item.status,paidAt:item.paidAt,isTransaction:true})); const allCalendarItems=useMemo(()=>[...events,...transactionEvents],[events,calendarTransactions]); const today=new Intl.DateTimeFormat('en-CA').format(new Date()); const isPaid=(item:any)=>item.status==='Pago'||item.status==='Efetivada'||item.paidAt||item.paid; const matchesFilter=(item:any)=>calendarFilter==='all'||(calendarFilter==='income'?item.type==='income':item.type!=='income'); const monthEvents=useMemo(()=>allCalendarItems.filter(e=>e.date.startsWith(monthKey)&&matchesFilter(e)),[allCalendarItems,monthKey,calendarFilter]); const eventsByDate=useMemo(()=>{const grouped=new Map<string,any[]>();monthEvents.forEach(item=>grouped.set(item.date,[...(grouped.get(item.date)||[]),item]));return grouped},[monthEvents]); const selectedEvents=useMemo(()=>selectedDate?allCalendarItems.filter(item=>item.date===selectedDate&&matchesFilter(item)):[],[allCalendarItems,selectedDate,calendarFilter]); const upcoming=useMemo(()=>allCalendarItems.filter(item=>item.type!=='income'&&!isPaid(item)).sort((a,b)=>a.date.localeCompare(b.date)),[allCalendarItems]); const monthSummary=useMemo(()=>{const items=allCalendarItems.filter(item=>item.date.startsWith(monthKey));return {income:items.filter(item=>item.type==='income').reduce((sum,item)=>sum+Number(item.value||0),0),expense:items.filter(item=>item.type!=='income').reduce((sum,item)=>sum+Number(item.value||0),0),overdue:items.filter(item=>item.type!=='income'&&!isPaid(item)&&item.date<today).reduce((sum,item)=>sum+Number(item.value||0),0)}},[allCalendarItems,monthKey,today]); const title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month).replace(/^./,x=>x.toUpperCase()); const selectedTitle=selectedDate?new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long'}).format(new Date(selectedDate+'T12:00:00')):''; const relativeDue=(date:string)=>{const days=Math.round((new Date(date+'T12:00:00').getTime()-new Date(today+'T12:00:00').getTime())/86400000);return days<0?`Vencida há ${Math.abs(days)} ${Math.abs(days)===1?'dia':'dias'}`:days===0?'Vence hoje':days===1?'Vence amanhã':days<=7?`Vence em ${days} dias`:new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(date+'T12:00:00')).replace('.','')};
  function SelectedDay(){const income=selectedEvents.filter(item=>item.type==='income').reduce((sum,item)=>sum+Number(item.value||0),0);const expense=selectedEvents.filter(item=>item.type!=='income').reduce((sum,item)=>sum+Number(item.value||0),0);return <div className="selected-day"><div className="selected-day-head"><span>DIA SELECIONADO</span><h3>{selectedTitle}</h3><p>{selectedEvents.length} {selectedEvents.length===1?'compromisso':'compromissos'}{income>0?` · ${brl(income)} a receber`:''}{expense>0?` · ${brl(expense)} a pagar`:''}</p></div>{selectedEvents.length?<div className="selected-event-list">{selectedEvents.map(item=><button key={item.id} onClick={()=>item.isTransaction?appAction({page:'Transações'}):setEditing({...item,value:String(item.value).replace('.',',')})}><i className={calendarStatusClass(item)}/><span><b>{item.title}</b><small>{item.category||calendarCategory(item)}</small></span><strong>{calendarValue(item)}</strong></button>)}</div>:<p className="selected-empty">Nenhum compromisso em {selectedTitle}.</p>}<button className="ghost selected-add" onClick={()=>openNew(selectedDate||undefined)}><Plus size={16}/> Adicionar evento neste dia</button></div>}
  return <div className="page-stack calendar-page"><div className="page-heading"><div><p>Minha agenda</p><h1>Calendário financeiro</h1><span>Nenhum compromisso fica para trás.</span></div><button className="primary" onClick={()=>openNew()}><Plus size={18}/> Novo evento</button></div><section className="calendar-summary" aria-label="Resumo financeiro do mês"><div><span>A receber</span><strong>{calendarValueVisibility.income?brl(monthSummary.income):'••••'}</strong></div><div><span>A pagar</span><strong>{calendarValueVisibility.expense?brl(monthSummary.expense):'••••'}</strong></div><div className="overdue"><span>Vencido</span><strong>{calendarValueVisibility.expense?brl(monthSummary.overdue):'••••'}</strong></div></section><div className="calendar-layout"><section className="card calendar"><div className="calendar-toolbar"><div className="calendar-title-nav"><h3>{title}</h3><div><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex-1,1))} aria-label="Mês anterior">‹</button><button className="ghost" onClick={()=>{const now=new Date();setMonth(now);setSelectedDate(new Intl.DateTimeFormat('en-CA').format(now))}} aria-label="Ir para hoje">Hoje</button><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex+1,1))} aria-label="Próximo mês">›</button></div></div><div className="calendar-filter" role="group" aria-label="Filtrar eventos">{([['all','Todas'],['income','Receitas'],['expense','Despesas']] as const).map(([value,label])=><button key={value} className={calendarFilter===value?'active':''} aria-pressed={calendarFilter===value} onClick={()=>setCalendarFilter(value)}>{label}</button>)}</div><div className="calendar-status-legend" aria-label="Legenda"><span className="paid"><i/> Pagas</span><span className="overdue"><i/> Vencidas</span><span className="upcoming"><i/> Próximas</span></div></div><div className="weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><b key={x}>{x}</b>)}</div><div className="days">{cells.map((day,i)=>{const valid=day>=1&&day<=daysInMonth;const date=valid?`${monthKey}-${String(day).padStart(2,'0')}`:'';const dayEvents:any[]=valid?(eventsByDate.get(date)||[]):[];return <div className={`${!valid?'muted ':''}${date===today?'today ':''}${date===selectedDate?'selected':''}`.trim()} key={i}><button className="day-select" onClick={()=>valid&&setSelectedDate(date)} disabled={!valid} aria-label={valid?`${day} de ${title}${dayEvents.length?`, ${dayEvents.length} compromissos`:''}`:''} aria-pressed={date===selectedDate}><span className="day-number">{valid?day:''}</span><span className="mobile-event-dots">{dayEvents.slice(0,3).map(e=><i className={calendarStatusClass(e)} key={e.id}/>)}</span></button>{dayEvents.slice(0,2).map(e=><button className={`calendar-event ${e.type} ${calendarStatusClass(e)}`} onClick={()=>e.isTransaction?appAction({page:'Transações'}):setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}><b>{e.title||calendarCategory(e)}</b><strong>{calendarValue(e)}</strong></button>)}{dayEvents.length>2&&<button className="calendar-more" onClick={()=>setSelectedDate(date)}>+{dayEvents.length-2}</button>}</div>})}</div><small className="calendar-hint">Selecione um dia para ver todos os compromissos.</small><div className="selected-day-mobile">{selectedDate&&<SelectedDay/>}</div></section><aside className="calendar-side"><div className="card selected-day-panel">{selectedDate?<SelectedDay/>:<div className="selected-placeholder"><CalendarDays/><h3>Selecione um dia</h3><p>Veja valores e compromissos da data.</p></div>}</div><section className="card agenda"><div className="agenda-head"><div><span>AGENDA</span><h3>Próximos vencimentos</h3></div>{upcoming.length>6&&<button className="text-button" onClick={()=>setShowAllUpcoming(!showAllUpcoming)}>{showAllUpcoming?'Ver menos':'Ver todos →'}</button>}</div>{upcoming.length?(showAllUpcoming?upcoming:upcoming.slice(0,6)).map(e=><button className={`agenda-date ${calendarStatusClass(e)}`} onClick={()=>{setSelectedDate(e.date);setMonth(new Date(e.date+'T12:00:00'))}} key={e.id}><b>{e.date.slice(-2)}<small>{new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(e.date+'T12:00:00')).replace('.','').toUpperCase()}</small></b><span><small>{e.title}</small><em>{e.category||'Evento'} · {relativeDue(e.date)}</em></span><strong>{calendarValue(e)}</strong></button>):<div className="agenda-empty"><b>✓ Tudo em dia</b><p>Nenhum vencimento próximo.</p></div>}</section></aside></div>
            {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal calendar-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO EVENTO':'EDITAR EVENTO'}</span><h2>{editing.isNew?'Adicionar compromisso':'Atualizar compromisso'}</h2><p>Organize datas, valores e responsáveis.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="calendar-edit-grid"><label className="field-full">Título<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Conta de energia" required/></label><label>Data<input type="date" value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value,status:e.target.value==='income'?'Efetivada':editing.status||'Pendente',paidAt:e.target.value==='income'?new Date().toISOString():editing.paidAt})}><option value="bill">Conta</option><option value="income">Receita</option><option value="card">Cartão</option><option value="sub">Assinatura</option><option value="goal">Meta</option></select></label><label>Valor<input value={editing.value} onChange={e=>setEditing({...editing,value:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal"/></label><label>Responsável<select value={editing.person} onChange={e=>setEditing({...editing,person:e.target.value})}><option value="Rafael">Você</option></select></label>{editing.type!=='income'&&<label>Situação<select value={editing.status||'Pendente'} onChange={e=>{const paid=e.target.value==='Pago';setEditing({...editing,status:e.target.value,paidAt:paid?(editing.paidAt||new Date().toISOString()):null})}}><option value="Pendente">Pendente</option><option value="Pago">Pago</option></select></label>}<label className="field-full">Observações<textarea value={editing.notes||''} onChange={e=>setEditing({...editing,notes:e.target.value})} placeholder="Detalhes opcionais" rows={3}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir evento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar evento</button></div></form></div>}
  </div>
}

