  const rememberDescription=()=>{const category=form.category;const description=form.description.trim();if(type!=='Despesa'||!category||!description||descriptionNames.some(item=>item.toLocaleLowerCase('pt-BR')===description.toLocaleLowerCase('pt-BR')))return;const next={...customDescriptionSuggestions,[category]:[...(customDescriptionSuggestions[category]||[]),description]};setCustomDescriptionSuggestions(next);try{const settings=JSON.parse(localStorage.getItem('juntos-settings')||'{}');localStorage.setItem('juntos-settings',JSON.stringify({...settings,descriptionSuggestions:next}))}catch{}};
