  const submit=(event:React.FormEvent)=>{event.preventDefault();const parsed=Number(form.value.replace(/[.]/g,'').replace(',','.'));if(form.schedule==='repeat'&&form.recurrenceDuration==='defined'&&Number(form.repeatCount)<2)return;if(!form.description.trim()||!parsed||!form.account)return;if(type==='Transferência'){if(!form.destinationAccount||form.destinationAccount===form.account)return;success({...form,title:form.description.trim(),value:parsed,type:'transfer',category:'',payment:'',card:'',behavior:undefined,schedule:'once'});close();return}const typed=form.categoryQuery.trim();const category=form.category||categoryNames.find(name=>name.toLocaleLowerCase('pt-BR')===typed.toLocaleLowerCase('pt-BR'))||typed;if(!category||!form.payment)return;if(type==='Despesa'){rememberDescription();if(!categoryNames.some(name=>name.toLocaleLowerCase('pt-BR')===category.toLocaleLowerCase('pt-BR'))){try{const settings=JSON.parse(localStorage.getItem('juntos-settings')||'{}');localStorage.setItem('juntos-settings',JSON.stringify({...settings,categories:[...new Set([...(settings.categories||[]),category])]}))}catch{}}}const icon=customCategoryIcons[category]||REVENUE_CATEGORY_ICONS[category]||EXPENSE_CATEGORY_ICONS[category]||categoryIconFor(category);success({...form,title:form.description.trim(),category,value:parsed,type:type==='Receita'?'in':'out',status:type==='Despesa'?form.expenseStatus:undefined,icon,behavior:type==='Despesa'?form.behavior:undefined,card:type==='Despesa'?form.card:'',destinationAccount:undefined});close()};
