  const isCreditPayment=type==='Despesa'&&form.payment==='Crédito';
  const descriptionField=<label className="field-full transaction-mobile-half description-picker">Descrição<input value={form.description} onFocus={()=>type==='Despesa'&&form.category&&setDescriptionOpen(true)} onBlur={()=>{setDescriptionOpen(false);rememberDescription()}} onChange={event=>{set('description',event.target.value);if(type==='Despesa')setDescriptionOpen(true)}} placeholder={type==='Despesa'?(form.category?'Selecione ou digite...':'Escolha a categoria primeiro'):'Digite a descrição'} autoComplete="off" required/>{descriptionOpen&&descriptionNames.length>0&&<div className="description-suggestions">{descriptionNames.filter(name=>!form.description.trim()||name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(form.description.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())).map(name=><button type="button" onMouseDown={event=>event.preventDefault()} onClick={()=>{set('description',name);setDescriptionOpen(false)}} key={name}><span>{name}</span></button>)}<button type="button" className="create-description-option" onMouseDown={event=>event.preventDefault()} onClick={()=>setDescriptionOpen(false)}><Plus size={16}/><span>Usar texto personalizado</span></button></div>}</label>;
