      {type==='Transferência'?<><label>De onde<select value={form.account} onChange={event=>set('account',event.target.value)} required>{accountOptions}</select></label><label>Para onde<select value={form.destinationAccount} onChange={event=>set('destinationAccount',event.target.value)} required>{accountOptions}</select>{form.account&&form.destinationAccount===form.account&&<small>Escolha uma conta diferente da origem.</small>}</label></>:type==='Receita'?<><label>Conta de destino<select value={form.account} onChange={event=>set('account',event.target.value)} required>{accountOptions}</select></label><label>Forma de recebimento<select value={form.payment} onChange={event=>set('payment',event.target.value)} required><option value="">Selecione</option>{['Pix','Transferência','Dinheiro','Depósito','Boleto'].map(option=><option key={option}>{option}</option>)}</select></label></>:<><label>Forma de pagamento<select value={form.payment} onChange={event=>{const payment=event.target.value;setForm(previous=>({...previous,payment,account:payment==='Crédito'?previous.card:previous.card?'':previous.account,card:payment==='Crédito'?previous.card:'',schedule:payment!=='Crédito'&&previous.schedule==='installments'?'once':previous.schedule,installments:payment!=='Crédito'?1:previous.installments}))}} required><option value="">Selecione</option><option>Pix</option><option>Débito</option><option value="Crédito">Cartão de crédito</option><option>Dinheiro</option><option>Boleto</option><option>Transferência</option></select></label>{isCreditPayment?<><label>Cartão<select value={form.card} onChange={event=>{const card=event.target.value;setForm(previous=>({...previous,card,account:card}))}} required><option value="">Selecione</option>{availableCards.map(card=>{const label=card.last4?`${card.bank} final ${card.last4}`:card.bank;return <option value={label} key={card.id}>{label} · {(card.scope||'personal')==='shared'?'Compartilhado':(card.holder||'Não informado')}</option>})}</select></label><label>Parcelamento<select value={form.schedule==='installments'?form.installments:1} onChange={event=>{const installments=Number(event.target.value);setForm(previous=>({...previous,installments,schedule:installments>1?'installments':'once'}))}}>{Array.from({length:36},(_,index)=>index+1).map(number=><option value={number} key={number}>{number}x</option>)}</select></label></>:<label>Conta / Cartão<select value={form.account} onChange={event=>set('account',event.target.value)} required>{accountOptions}</select></label>}</>}
