      const cardAlerts:any[]=cards.map(card=>{const invoice=Number(card.invoice||0),limit=Number(card.limit||0),excess=invoice-limit;return excess>0?{id:`card-limit-${card.id}-${Math.round(excess*100)}`,title:'Limite do cartão ultrapassado',text:`${card.bank||'Cartão'}: ${brl(excess)} acima do limite.`,time:'Cartões',read:false}:null}).filter(Boolean);
