      const alerts=[...overdueEventAlerts,...overdueTransactionAlerts,...overdueDebtAlerts,...budgetAlerts,...cardAlerts,...events.filter(item=>item.date>=today&&item.date<=limit&&!isPaid(item)).map(item=>({id:'event-'+item.id,title:'Vencimento próximo',text:`${item.title} vence em ${new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR')}`,time:'Calendário',read:false})),...tx.filter(item=>item.type==='out'&&item.dateInput>=today&&item.dateInput<=limit&&!isPaid(item)).map(item=>({id:'tx-'+item.id,title:item.installments>1?'Parcela próxima':'Pagamento previsto',text:`${item.title}: ${brl(Number(item.value))}`,time:new Date(item.dateInput+'T12:00:00').toLocaleDateString('pt-BR'),read:false})),...debts.filter(item=>Number(item.paid)<Number(item.total)&&item.due>=today&&item.due<=limit).map(item=>({id:'debt-'+item.id,title:'Dívida próxima do vencimento',text:`${item.name}: faltam ${brl(Number(item.total)-Number(item.paid))}`,time:new Date(item.due+'T12:00:00').toLocaleDateString('pt-BR'),read:false})),...subscriptions.filter(item=>item.active&&item.next>=today&&item.next<=limit).map(item=>({id:'sub-'+item.id,title:'Assinatura próxima',text:`${item.name}: ${brl(Number(item.value))}`,time:new Date(item.next+'T12:00:00').toLocaleDateString('pt-BR'),read:false}))];
