  useEffect(()=>{if(members.length)return;const saved=localStorage.getItem('juntos-settings');if(saved)try{const data=JSON.parse(saved);if(data.people)setPeople(data.people)}catch{}},[members.length]);
  useEffect(()=>{const loadBalances=()=>{const saved=localStorage.getItem('juntos-balances');try{setBalances(saved?{couple:0,rafael:0,mariana:0,investments:0,...JSON.parse(saved)}:{couple:0,rafael:0,mariana:0,investments:0})}catch{}};loadBalances();window.addEventListener('juntos-cloud-synced',loadBalances);window.addEventListener('storage',loadBalances);return()=>{window.removeEventListener('juntos-cloud-synced',loadBalances);window.removeEventListener('storage',loadBalances)}},[]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<{card:string}>).detail;setTransactionType('Despesa');setTransactionCard(detail.card);setModal(true)};window.addEventListener('juntos-card-expense',handler);return()=>window.removeEventListener('juntos-card-expense',handler)},[]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<string|{page:string}>).detail;if(typeof detail==='string'){setActionToast(detail);setToast(true);setTimeout(()=>setToast(false),2600)}else if(detail?.page){setActive(detail.page);window.scrollTo({top:0,behavior:'smooth'})}};window.addEventListener('juntos-action',handler);return()=>window.removeEventListener('juntos-action',handler)},[]);
  useEffect(()=>{const handler=(event:Event)=>setDialog((event as CustomEvent).detail);window.addEventListener('juntos-dialog',handler);return()=>window.removeEventListener('juntos-dialog',handler)},[]);
  useEffect(()=>{if(!dialog)return;const keyHandler=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!dialog.alert){dialog.resolve(false);setDialog(null)}};window.addEventListener('keydown',keyHandler);return()=>window.removeEventListener('keydown',keyHandler)},[dialog]);
  const closeDialog=(result:boolean)=>{dialog?.resolve(result);setDialog(null)};
  const saveProfile=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const name=people.Rafael.name.trim();if(!user||!name)return;const supabase=createBrowserClient();const {error}=await supabase.from('profiles').update({full_name:name}).eq('id',user.id);if(error){await alertDialog('Não foi possível alterar o nome. Tente novamente.');return}const {error:metadataError}=await supabase.auth.updateUser({data:{full_name:name}});if(metadataError){await alertDialog('O nome foi salvo no perfil, mas não foi possível atualizar a conta.');return}const current=JSON.parse(localStorage.getItem('juntos-settings')||'{}');localStorage.setItem('juntos-settings',JSON.stringify({...current,people:{...people,Rafael:{...people.Rafael,name}}}));await refresh();setProfileOpen(false);setActionToast('Nome atualizado com sucesso.');setToast(true);setTimeout(()=>setToast(false),3000)};
  const saveTransaction=(data:any)=>{const saved=localStorage.getItem('juntos-transactions');const current=saved?JSON.parse(saved):transactions;const schedule=data.schedule||'once';const repeatUnit=data.repeatUnit||'month';const count=schedule==='installments'?Math.max(2,Number(data.installments)||2):schedule==='repeat'?(data.recurrenceDuration==='defined'?Math.max(2,Number(data.repeatCount)):24):schedule==='fixed'?24:1;const seriesId=Date.now();const addMonths=(input:string,amount:number)=>{const [year,month,day]=input.split('-').map(Number);const target=new Date(year,month-1+amount,1);const safeDay=Math.min(day,new Date(target.getFullYear(),target.getMonth()+1,0).getDate());return target.getFullYear()+'-'+String(target.getMonth()+1).padStart(2,'0')+'-'+String(safeDay).padStart(2,'0')};const addDays=(input:string,amount:number)=>{const [year,month,day]=input.split('-').map(Number);const target=new Date(year,month-1,day+amount);return target.getFullYear()+'-'+String(target.getMonth()+1).padStart(2,'0')+'-'+String(target.getDate()).padStart(2,'0')};const dateForIndex=(index:number)=>schedule==='repeat'?(repeatUnit==='day'?addDays(data.date,index):repeatUnit==='week'?addDays(data.date,index*7):addMonths(data.date,index)):addMonths(data.date,index);const generated=Array.from({length:count},(_,index)=>{const dateInput=dateForIndex(index);const date=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(dateInput+'T12:00:00')).replace('.','');const installment=schedule==='installments';const futureExpense=data.type==='out'&&dateInput>new Intl.DateTimeFormat('en-CA').format(new Date());const awaitingValue=data.type==='out'&&schedule==='repeat'&&data.behavior==='variable'&&index>0;const paid=!awaitingValue&&!futureExpense&&data.status==='Pago';return {id:seriesId+index,title:installment?data.title+' ('+(index+1)+'/'+count+')':data.title,category:data.category,person:data.person,account:data.account,destinationAccount:data.destinationAccount,payment:data.payment,card:data.card,date,dateInput,value:awaitingValue?0:data.value,expectedValue:awaitingValue?data.value:undefined,type:data.type,icon:data.icon,seriesId,schedule,repeatUnit,recurrenceDuration:data.recurrenceDuration,repeatCount:schedule==='repeat'&&data.recurrenceDuration==='defined'?count:undefined,continuous:schedule==='repeat'&&data.recurrenceDuration==='continuous',recurring:schedule==='repeat'||schedule==='fixed',fixedMonthly:schedule==='fixed',behavior:data.behavior||(schedule==='installments'?'installments':schedule==='fixed'?'fixed':'variable'),goalDepositId:data.goalDepositId,installment:index+1,installments:installment?count:1,createdAt:new Date().toISOString(),status:data.type==='out'?(awaitingValue?'Aguardando valor':paid?'Pago':'Pendente'):'Efetivada',paidAt:data.type==='out'?(paid?new Date().toISOString():null):new Date().toISOString()}});const next=[...generated,...current].sort((a,b)=>(b.dateInput||'').localeCompare(a.dateInput||''));localStorage.setItem('juntos-transactions',JSON.stringify(next));if(data.card&&data.type==='out'){try{const savedCards=JSON.parse(localStorage.getItem('juntos-cards')||'[]');const charged=Number(generated[0]?.value||data.value||0);const updatedCards=savedCards.map((item:any)=>(item.last4?item.bank+' final '+item.last4:item.bank)===data.card?{...item,invoice:Number(item.invoice||0)+charged,future:Number(item.future||0)+Math.max(0,Number(data.value||0)-charged)}:item);localStorage.setItem('juntos-cards',JSON.stringify(updatedCards));window.dispatchEvent(new Event('juntos-cards-updated'))}catch{}}const balanceKey=(name:string)=>name==='Conta Rafael'?'rafael':name==='Conta Mariana'?'mariana':name==='Conta do casal'?'couple':null;const accountKey=balanceKey(data.account);const destinationKey=balanceKey(data.destinationAccount);if(accountKey||destinationKey){setBalances(previous=>{const updated={...previous};if(accountKey)updated[accountKey as keyof typeof updated]=Math.max(0,Number(updated[accountKey as keyof typeof updated]||0)+(data.type==='in'?data.value:-data.value));if(data.type==='transfer'&&destinationKey)updated[destinationKey as keyof typeof updated]=Math.max(0,Number(updated[destinationKey as keyof typeof updated]||0)+data.value);localStorage.setItem('juntos-balances',JSON.stringify(updated));return updated})}window.dispatchEvent(new Event('juntos-transactions-updated'));setActionToast(schedule==='fixed'?'Transação fixa mensal criada.':schedule==='repeat'?('Repetição '+(repeatUnit==='day'?'diária':repeatUnit==='week'?'semanal':repeatUnit==='fortnight'?'quinzenal':'mensal')+' criada com sucesso.'):schedule==='installments'?'Compra parcelada com sucesso.':data.category==='Salário'&&data.type==='in'?'Salário adicionado ao seu saldo!':'Transação adicionada com sucesso!');setToast(true);setTimeout(()=>setToast(false),3000)};
  const togglePrivacy=()=>setHidden(previous=>{const next=!previous;localStorage.setItem('juntos-private-mode',String(next));return next});
  const openTransaction=(type='Despesa')=>{setTransactionType(type);setTransactionCard('');setModal(true)};
  const unread=notifications.filter(n=>!n.read).length;
  const content=useMemo(()=>{const p:any={Dashboard:<Dashboard onNew={openTransaction} onAi={()=>setActive('IA Conselheira')} hidden={hidden} onTogglePrivacy={togglePrivacy} people={people} currentName={loggedName} isCouple={isCouple}/>,"Transações":<TransactionsPage onNew={openTransaction} people={people} isCouple={isCouple}/>,"Orçamentos":<BudgetsPage/>,"Contas":<AccountsPage people={people} setPeople={setPeople} balances={balances} setBalances={setBalances} isCouple={isCouple}/>,"Cartões":<CardsPage people={people} onTransaction={saveTransaction} isCouple={isCouple} hidden={hidden}/>,"Calendário":<CalendarPage people={people}/>,Metas:<GoalsPage onTransaction={saveTransaction} isCouple={isCouple} people={people} hidden={hidden}/>,Assinaturas:<SubscriptionsPage onTransaction={saveTransaction} hidden={hidden} onTogglePrivacy={togglePrivacy}/>,Compras:<PurchasesPage onFinish={saveTransaction} hidden={hidden} onTogglePrivacy={togglePrivacy}/>,"Calculadora de investimentos":<InvestmentCalculator hidden={hidden} onTogglePrivacy={togglePrivacy}/>,"Relatórios":<ReportsDashboard people={people} hidden={hidden} onTogglePrivacy={togglePrivacy}/>,"IA Conselheira":<AiPage people={people} hidden={hidden}/>,"Configurações":<SettingsPage dark={dark} setDark={setDark} people={people} setPeople={setPeople} hidden={hidden} onTogglePrivacy={togglePrivacy}/>};return p[active]||<Placeholder title={active} onGo={()=>setActive('Dashboard')}/>},[active,hidden,dark,people,balances,isCouple,loggedName]);
